/**
 * Cross-platform crypto interop test.
 *
 * Verifies that the JavaScript crypto implementation (hpke-js + @noble/*)
 * produces output compatible with the Rust llamenos-core implementation by
 * consuming test vectors generated by `llamenos-core/tests/interop.rs`.
 *
 * Run the Rust test first to generate vectors:
 *   cd packages/crypto && cargo test --test interop
 *
 * Then run this test:
 *   bun run test -- tests/crypto-interop.spec.ts
 */

import { test, expect } from '@playwright/test'
import { readFileSync, existsSync } from 'fs'
import { resolve, dirname } from 'path'
import { fileURLToPath } from 'url'
import { sha256 } from '@noble/hashes/sha2.js'
import { gcm } from '@noble/ciphers/aes.js'
import { bytesToHex, hexToBytes, utf8ToBytes } from '@noble/hashes/utils.js'
import { ed25519, x25519 } from '@noble/curves/ed25519.js'
import { hkdf } from '@noble/hashes/hkdf.js'
import { CipherSuite, KemId, KdfId, AeadId } from 'hpke-js'
import * as labels from '../packages/shared/crypto-labels'

const __filename = fileURLToPath(import.meta.url)
const __dirname = dirname(__filename)
const VECTORS_PATH = resolve(__dirname, '../packages/crypto/tests/fixtures/test-vectors.json')

// Skip if test vectors haven't been generated yet
const hasVectors = existsSync(VECTORS_PATH)
const vectors = hasVectors ? JSON.parse(readFileSync(VECTORS_PATH, 'utf-8')) : null

/** HPKE suite matching Rust: DHKEM(X25519, HKDF-SHA256) + HKDF-SHA256 + AES-256-GCM */
const hpkeSuite = new CipherSuite({
  kem: KemId.DhkemX25519HkdfSha256,
  kdf: KdfId.HkdfSha256,
  aead: AeadId.Aes256Gcm,
})

test.describe('Cross-platform crypto interop', () => {
  test.skip(!hasVectors, 'Test vectors not found — run: cd packages/crypto && cargo test --test interop')

  test('label constants match Rust', () => {
    const rustLabels = vectors.labels

    expect(labels.LABEL_NOTE_KEY).toBe(rustLabels.labelNoteKey)
    expect(labels.LABEL_FILE_KEY).toBe(rustLabels.labelFileKey)
    expect(labels.LABEL_FILE_METADATA).toBe(rustLabels.labelFileMetadata)
    expect(labels.LABEL_HUB_KEY_WRAP).toBe(rustLabels.labelHubKeyWrap)
    expect(labels.LABEL_TRANSCRIPTION).toBe(rustLabels.labelTranscription)
    expect(labels.LABEL_MESSAGE).toBe(rustLabels.labelMessage)
    expect(labels.LABEL_CALL_META).toBe(rustLabels.labelCallMeta)
    expect(labels.LABEL_SHIFT_SCHEDULE).toBe(rustLabels.labelShiftSchedule)
    expect(labels.HKDF_SALT).toBe(rustLabels.hkdfSalt)
    expect(labels.HKDF_CONTEXT_NOTES).toBe(rustLabels.hkdfContextNotes)
    expect(labels.HKDF_CONTEXT_DRAFTS).toBe(rustLabels.hkdfContextDrafts)
    expect(labels.HKDF_CONTEXT_EXPORT).toBe(rustLabels.hkdfContextExport)
    expect(labels.LABEL_HUB_EVENT).toBe(rustLabels.labelHubEvent)
    expect(labels.LABEL_DEVICE_PROVISION).toBe(rustLabels.labelDeviceProvision)
    expect(labels.SAS_SALT).toBe(rustLabels.sasSalt)
    expect(labels.SAS_INFO).toBe(rustLabels.sasInfo)
    expect(labels.AUTH_PREFIX).toBe(rustLabels.authPrefix)
    expect(labels.HMAC_PHONE_PREFIX).toBe(rustLabels.hmacPhonePrefix)
    expect(labels.HMAC_IP_PREFIX).toBe(rustLabels.hmacIpPrefix)
    expect(labels.HMAC_KEYID_PREFIX).toBe(rustLabels.hmacKeyidPrefix)
    expect(labels.HMAC_SUBSCRIBER).toBe(rustLabels.hmacSubscriber)
    expect(labels.HMAC_PREFERENCE_TOKEN).toBe(rustLabels.hmacPreferenceToken)
    expect(labels.RECOVERY_SALT).toBe(rustLabels.recoverySalt)
    expect(labels.LABEL_BACKUP).toBe(rustLabels.labelBackup)
    expect(labels.LABEL_SERVER_NOSTR_KEY).toBe(rustLabels.labelServerNostrKey)
    expect(labels.LABEL_SERVER_NOSTR_KEY_INFO).toBe(rustLabels.labelServerNostrKeyInfo)
    expect(labels.LABEL_PUSH_WAKE).toBe(rustLabels.labelPushWake)
    expect(labels.LABEL_PUSH_FULL).toBe(rustLabels.labelPushFull)
    expect(labels.LABEL_AUDIT_USER_KEY_WRAP).toBe(rustLabels.labelAuditUserKeyWrap)
    expect(labels.LABEL_ERASURE_OVERRIDE_SIG).toBe(rustLabels.labelErasureOverrideSig)
    expect(labels.LABEL_AUDIT_DETAILS).toBe(rustLabels.labelAuditDetails)
    expect(labels.LABEL_DEVICE_WIPE_SIG).toBe(rustLabels.labelDeviceWipeSig)
  })

  test('JS derives same X25519 pubkey from test secret key', () => {
    const secretKeyHex = vectors.keys.secretKeyHex
    const expectedPubkey = vectors.keys.x25519PubkeyHex

    // X25519 public key derivation — uses top-level ESM import of @noble/curves
    const pubkey = x25519.getPublicKey(hexToBytes(secretKeyHex))
    expect(bytesToHex(pubkey)).toBe(expectedPubkey)
  })

  test('JS derives same admin X25519 pubkey', () => {
    const secretKeyHex = vectors.keys.adminSecretKeyHex
    const expectedPubkey = vectors.keys.adminX25519PubkeyHex

    // X25519 pubkey derivation — uses top-level ESM import of @noble/curves
    const pubkey = x25519.getPublicKey(hexToBytes(secretKeyHex))
    expect(bytesToHex(pubkey)).toBe(expectedPubkey)
  })

  test('JS can unwrap HPKE envelope produced by Rust', async () => {
    const { envelope, originalKeyHex, label } = vectors.hpke
    const adminSecretKey = vectors.keys.adminSecretKeyHex

    const decrypted = await hpkeUnwrap(envelope, adminSecretKey, label)
    expect(bytesToHex(decrypted)).toBe(originalKeyHex)
  })

  test('JS can decrypt note produced by Rust (author key)', async () => {
    const { encrypted, plaintextJson } = vectors.noteEncryption
    const authorSecretKey = vectors.keys.secretKeyHex

    const noteKey = await hpkeUnwrap(encrypted.authorEnvelope, authorSecretKey, labels.LABEL_NOTE_KEY)
    const decoded = decryptContent(encrypted.encryptedContent, noteKey, labels.LABEL_NOTE_KEY)
    expect(decoded).toBe(plaintextJson)
  })

  test('JS can decrypt note produced by Rust (admin key)', async () => {
    const { encrypted, plaintextJson } = vectors.noteEncryption
    const adminSecretKey = vectors.keys.adminSecretKeyHex
    const adminPubkey = vectors.keys.adminX25519PubkeyHex

    const adminEnvelope = encrypted.adminEnvelopes.find(
      (e: { pubkey: string }) => e.pubkey === adminPubkey,
    )
    expect(adminEnvelope).toBeDefined()

    const noteKey = await hpkeUnwrap(adminEnvelope, adminSecretKey, labels.LABEL_NOTE_KEY)
    const decoded = decryptContent(encrypted.encryptedContent, noteKey, labels.LABEL_NOTE_KEY)
    expect(decoded).toBe(plaintextJson)
  })

  test('JS can verify auth token produced by Rust', () => {
    const { token, method, path } = vectors.auth

    // Reconstruct the Ed25519 auth message — must match Rust build_auth_message_with_nonce():
    // Format: LABEL_DEVICE_AUTH:pubkey:timestamp:method:path[:nonce]
    // Signed as raw UTF-8 bytes (no SHA-256 pre-hash)
    const base = `${labels.LABEL_DEVICE_AUTH}:${token.pubkey}:${token.timestamp}:${method}:${path}`
    const message = token.nonce ? `${base}:${token.nonce}` : base

    // Verify Ed25519 signature (signs raw message bytes, no SHA-256 pre-hash)
    const valid = ed25519.verify(hexToBytes(token.token), utf8ToBytes(message), hexToBytes(token.pubkey))
    expect(valid).toBe(true)
  })

  test('JS can decrypt draft produced by Rust', () => {
    const { encryptedHex, secretKeyHex, plaintext } = vectors.draftEncryption

    // Draft encryption uses HKDF-derived key from the secret key
    const hkdfKey = hkdf(sha256, hexToBytes(secretKeyHex), utf8ToBytes(labels.HKDF_SALT), utf8ToBytes(labels.HKDF_CONTEXT_DRAFTS), 32)

    // Parse: nonce(12) + ciphertext + tag(16)
    const packed = hexToBytes(encryptedHex)
    const nonce = packed.slice(0, 12)
    const ciphertext = packed.slice(12)

    const cipher = gcm(hkdfKey, nonce, utf8ToBytes(labels.HKDF_CONTEXT_DRAFTS))
    const decrypted = cipher.decrypt(ciphertext)
    const decoded = new TextDecoder().decode(decrypted)

    expect(decoded).toBe(plaintext)
  })

  test('PIN encryption structure matches expected format', () => {
    const { encrypted, pin } = vectors.pinEncryption

    // Validate structure (don't decrypt — Argon2id is too slow in Playwright)
    expect(encrypted.salt).toHaveLength(64) // 32 bytes hex
    expect(encrypted.nonce).toHaveLength(24) // 12 bytes hex (AES-256-GCM)
    expect(encrypted.ciphertext).toBeTruthy()
    expect(encrypted.pubkey).toBeTruthy()
    expect(pin).toBe('12345678')
  })

  // ─── v3 Tests (HPKE + AES-256-GCM) ────────────────────────────

  test('JS can decrypt message produced by Rust (volunteer)', async () => {
    const { encrypted, plaintext } = vectors.messageEncryption
    const volSecretKey = vectors.keys.secretKeyHex
    const volPubkey = vectors.keys.x25519PubkeyHex

    // Find volunteer's envelope
    const volEnvelope = encrypted.readerEnvelopes.find(
      (e: { pubkey: string }) => e.pubkey === volPubkey,
    )
    expect(volEnvelope).toBeDefined()

    // Unwrap message key via HPKE with LABEL_MESSAGE
    const msgKey = await hpkeUnwrap(volEnvelope, volSecretKey, labels.LABEL_MESSAGE)

    // Decrypt content
    const decoded = decryptContent(encrypted.encryptedContent, msgKey, labels.LABEL_MESSAGE)
    expect(decoded).toBe(plaintext)
  })

  test('JS can decrypt message produced by Rust (admin)', async () => {
    const { encrypted, plaintext } = vectors.messageEncryption
    const adminSecretKey = vectors.keys.adminSecretKeyHex
    const adminPubkey = vectors.keys.adminX25519PubkeyHex

    const adminEnvelope = encrypted.readerEnvelopes.find(
      (e: { pubkey: string }) => e.pubkey === adminPubkey,
    )
    expect(adminEnvelope).toBeDefined()

    const msgKey = await hpkeUnwrap(adminEnvelope, adminSecretKey, labels.LABEL_MESSAGE)
    const decoded = decryptContent(encrypted.encryptedContent, msgKey, labels.LABEL_MESSAGE)
    expect(decoded).toBe(plaintext)
  })

  test('JS can unwrap hub key produced by Rust', async () => {
    const { hubKeyHex, wrappedEnvelopes, label } = vectors.hubKey
    const volSecretKey = vectors.keys.secretKeyHex

    // Unwrap first envelope (volunteer)
    const unwrapped = await hpkeUnwrap(wrappedEnvelopes[0], volSecretKey, label)
    expect(bytesToHex(unwrapped)).toBe(hubKeyHex)

    // Unwrap second envelope (admin)
    const adminUnwrapped = await hpkeUnwrap(
      wrappedEnvelopes[1],
      vectors.keys.adminSecretKeyHex,
      label,
    )
    expect(bytesToHex(adminUnwrapped)).toBe(hubKeyHex)
  })

  test('JS can decrypt export produced by Rust', () => {
    const { encryptedBase64, secretKeyHex, plaintextJson } = vectors.exportEncryption

    // Derive key using HKDF with HKDF_CONTEXT_EXPORT
    const exportKey = hkdf(
      sha256,
      hexToBytes(secretKeyHex),
      utf8ToBytes(labels.HKDF_SALT),
      utf8ToBytes(labels.HKDF_CONTEXT_EXPORT),
      32,
    )

    // Decode base64 → nonce(12) + ciphertext + tag(16)
    const packed = Uint8Array.from(atob(encryptedBase64), c => c.charCodeAt(0))
    const nonce = packed.slice(0, 12)
    const ciphertext = packed.slice(12)

    const cipher = gcm(exportKey, nonce, utf8ToBytes(labels.HKDF_CONTEXT_EXPORT))
    const decrypted = cipher.decrypt(ciphertext)
    const decoded = new TextDecoder().decode(decrypted)

    expect(decoded).toBe(plaintextJson)
  })

  test('JS can decrypt call record produced by Rust (admin)', async () => {
    const { encryptedContent, adminEnvelopes, plaintextJson } = vectors.callRecord
    const adminSecretKey = vectors.keys.adminSecretKeyHex
    const adminPubkey = vectors.keys.adminX25519PubkeyHex

    const adminEnvelope = adminEnvelopes.find(
      (e: { pubkey: string }) => e.pubkey === adminPubkey,
    )
    expect(adminEnvelope).toBeDefined()

    // Unwrap with LABEL_CALL_META (not LABEL_MESSAGE)
    const recordKey = await hpkeUnwrap(adminEnvelope, adminSecretKey, labels.LABEL_CALL_META)
    const decoded = decryptContent(encryptedContent, recordKey, labels.LABEL_CALL_META)
    expect(decoded).toBe(plaintextJson)
  })

  test('Domain separation prevents cross-label unwrap', async () => {
    const { wrappedWithNoteLabel, wrappedWithMessageLabel, wrappedWithHubLabel } =
      vectors.domainSeparation
    const adminSecretKey = vectors.keys.adminSecretKeyHex

    // Same-label unwrap succeeds
    await expect(hpkeUnwrap(wrappedWithNoteLabel, adminSecretKey, labels.LABEL_NOTE_KEY)).resolves.toBeDefined()
    await expect(hpkeUnwrap(wrappedWithMessageLabel, adminSecretKey, labels.LABEL_MESSAGE)).resolves.toBeDefined()
    await expect(hpkeUnwrap(wrappedWithHubLabel, adminSecretKey, labels.LABEL_HUB_KEY_WRAP)).resolves.toBeDefined()

    // Cross-label unwrap fails (AEAD verification failure)
    await expect(hpkeUnwrap(wrappedWithNoteLabel, adminSecretKey, labels.LABEL_MESSAGE)).rejects.toThrow()
    await expect(hpkeUnwrap(wrappedWithMessageLabel, adminSecretKey, labels.LABEL_NOTE_KEY)).rejects.toThrow()
    await expect(hpkeUnwrap(wrappedWithHubLabel, adminSecretKey, labels.LABEL_NOTE_KEY)).rejects.toThrow()
  })

  // ─── Adversarial Tests ─────────────────────────────────────

  test('HPKE unwrap with tampered ciphertext throws', async () => {
    const { tamperedCt, validEnvelope, validLabel } = vectors.adversarial.hpke
    const adminSecretKey = vectors.keys.adminSecretKeyHex

    const tamperedEnvelope = {
      ct: tamperedCt,
      enc: validEnvelope.enc,
    }
    await expect(hpkeUnwrap(tamperedEnvelope, adminSecretKey, validLabel)).rejects.toThrow()
  })

  test('HPKE unwrap with truncated data throws', async () => {
    const { truncatedCt, validEnvelope, validLabel } = vectors.adversarial.hpke
    const adminSecretKey = vectors.keys.adminSecretKeyHex

    const truncatedEnvelope = {
      ct: truncatedCt,
      enc: validEnvelope.enc,
    }
    await expect(hpkeUnwrap(truncatedEnvelope, adminSecretKey, validLabel)).rejects.toThrow()
  })

  test('HPKE unwrap with wrong key throws', async () => {
    const { validEnvelope, validLabel } = vectors.adversarial.hpke
    const wrongSecretKey = vectors.keys.wrongSecretKeyHex

    await expect(hpkeUnwrap(validEnvelope, wrongSecretKey, validLabel)).rejects.toThrow()
  })

  test('Note decrypt with tampered content throws', async () => {
    const { validEncrypted, tamperedContent } = vectors.adversarial.note
    const authorSecretKey = vectors.keys.secretKeyHex

    // Unwrap the note key (should succeed)
    const noteKey = await hpkeUnwrap(
      validEncrypted.authorEnvelope,
      authorSecretKey,
      labels.LABEL_NOTE_KEY,
    )

    // Decrypt tampered content (should fail — AES-256-GCM auth tag mismatch)
    const contentBytes = hexToBytes(tamperedContent)
    const contentNonce = contentBytes.slice(0, 12)
    const contentCiphertext = contentBytes.slice(12)

    expect(() => {
      const cipher = gcm(noteKey, contentNonce, utf8ToBytes(labels.LABEL_NOTE_KEY))
      cipher.decrypt(contentCiphertext)
    }).toThrow()
  })

  test('Auth token with wrong method fails verification', () => {
    const { validToken, validPath, wrongMethod } = vectors.adversarial.auth

    // New format: includes pubkey, raw UTF-8 (no SHA-256 pre-hash)
    const message = `${labels.LABEL_DEVICE_AUTH}:${validToken.pubkey}:${validToken.timestamp}:${wrongMethod}:${validPath}`
    const valid = ed25519.verify(hexToBytes(validToken.token), utf8ToBytes(message), hexToBytes(validToken.pubkey))
    expect(valid).toBe(false)
  })

  test('Auth token with wrong path fails verification', () => {
    const { validToken, validMethod, wrongPath } = vectors.adversarial.auth

    // New format: includes pubkey, raw UTF-8 (no SHA-256 pre-hash)
    const message = `${labels.LABEL_DEVICE_AUTH}:${validToken.pubkey}:${validToken.timestamp}:${validMethod}:${wrongPath}`
    const valid = ed25519.verify(hexToBytes(validToken.token), utf8ToBytes(message), hexToBytes(validToken.pubkey))
    expect(valid).toBe(false)
  })

  test('Message decrypt with wrong reader key fails', () => {
    const { validEncrypted } = vectors.adversarial.message
    const wrongPubkey = vectors.keys.wrongX25519PubkeyHex

    // Wrong key won't be found in envelopes
    const wrongEnvelope = validEncrypted.readerEnvelopes.find(
      (e: { pubkey: string }) => e.pubkey === wrongPubkey,
    )
    expect(wrongEnvelope).toBeUndefined()
  })

  // ─── Device provisioning key bundle (PROTOCOL.md 6.1.1) ─────

  test('device provisioning bundle decrypts to BOTH device seeds', () => {
    const p = vectors.provisioning

    // Rust used the generated label constants, not ad-hoc strings.
    expect(p.aadLabel).toBe(labels.LABEL_DEVICE_PROVISION_BUNDLE)
    expect(p.hkdfSalt).toBe(labels.LABEL_PROVISIONING_SALT)
    expect(p.hkdfInfo).toBe(labels.LABEL_DEVICE_PROVISION)

    // New-device side: ECDH against the primary's published X25519 pubkey.
    const shared = x25519.getSharedSecret(
      hexToBytes(p.ephemeralSecretHex),
      hexToBytes(p.primaryEncryptionPubkeyHex),
    )
    const provKey = hkdf(sha256, shared, utf8ToBytes(p.hkdfSalt), utf8ToBytes(p.hkdfInfo), 32)

    const data = hexToBytes(p.encryptedHex)
    const plaintext = gcm(provKey, data.slice(0, 12), utf8ToBytes(p.aadLabel)).decrypt(data.slice(12))

    // Bundle layout: version || signing seed || encryption seed
    expect(plaintext.length).toBe(p.bundleLen)
    expect(plaintext[0]).toBe(p.bundleVersion)
    const signingSeed = plaintext.slice(1, 33)
    const encryptionSeed = plaintext.slice(33, 65)
    expect(bytesToHex(signingSeed)).toBe(p.primarySigningSeedHex)
    expect(bytesToHex(encryptionSeed)).toBe(p.primaryEncryptionSeedHex)

    // The linked device therefore holds the primary's keypairs — which is what
    // lets it decrypt ciphertext wrapped to the primary before the link.
    expect(bytesToHex(ed25519.getPublicKey(signingSeed))).toBe(p.primarySigningPubkeyHex)
    expect(bytesToHex(x25519.getPublicKey(encryptionSeed))).toBe(p.primaryEncryptionPubkeyHex)

    // The two seeds are independent (PROTOCOL.md 2.11): re-deriving the
    // encryption seed from the signing seed produces a DIFFERENT key, i.e. a
    // device that authenticates and then silently decrypts nothing.
    const rederived = hkdf(sha256, signingSeed, new Uint8Array(0),
      utf8ToBytes(labels.LABEL_DEVICE_ENCRYPTION_SEED), 32)
    expect(bytesToHex(rederived)).not.toBe(p.primaryEncryptionSeedHex)
  })

  test('provisioning SAS matches the Rust-computed code', () => {
    const p = vectors.provisioning
    const shared = x25519.getSharedSecret(
      hexToBytes(p.ephemeralSecretHex),
      hexToBytes(p.primaryEncryptionPubkeyHex),
    )
    const sasBytes = hkdf(sha256, shared, utf8ToBytes(labels.SAS_SALT), utf8ToBytes(labels.SAS_INFO), 4)
    const num = ((sasBytes[0] << 24) | (sasBytes[1] << 16) | (sasBytes[2] << 8) | sasBytes[3]) >>> 0
    const code = (num % 1_000_000).toString().padStart(6, '0')
    expect(`${code.slice(0, 3)} ${code.slice(3)}`).toBe(p.sasCode)
  })

  test('provisioning bundle does not authenticate under the pre-bundle AAD', () => {
    // Domain separation is what prevents a silent downgrade to an older
    // provisioning payload format.
    const p = vectors.provisioning
    const shared = x25519.getSharedSecret(
      hexToBytes(p.ephemeralSecretHex),
      hexToBytes(p.primaryEncryptionPubkeyHex),
    )
    const provKey = hkdf(sha256, shared, utf8ToBytes(p.hkdfSalt), utf8ToBytes(p.hkdfInfo), 32)
    const data = hexToBytes(p.encryptedHex)

    expect(() =>
      gcm(provKey, data.slice(0, 12), utf8ToBytes(labels.LABEL_DEVICE_PROVISION)).decrypt(data.slice(12)),
    ).toThrow()
  })
})

// ─── Helpers ─────────────────────────────────────────────────

/**
 * HPKE unwrap: RFC 9180 DHKEM(X25519, HKDF-SHA256) + HKDF-SHA256 + AES-256-GCM.
 * info = label bytes, aad = "${label}:key-wrap" bytes.
 * Envelope fields: { enc: hex, ct: hex }
 */
async function hpkeUnwrap(
  envelope: { ct: string; enc: string },
  secretKeyHex: string,
  label: string,
): Promise<Uint8Array> {
  const recipientSk = await hpkeSuite.importKey('raw', Uint8Array.from(hexToBytes(secretKeyHex)).buffer, false)
  const enc = hexToBytes(envelope.enc)
  const ct = hexToBytes(envelope.ct)
  const info = utf8ToBytes(label)
  const aad = utf8ToBytes(`${label}:key-wrap`)

  const plaintext = await hpkeSuite.open(
    { recipientKey: recipientSk, enc, info },
    ct,
    aad,
  )

  return new Uint8Array(plaintext)
}

/** Decrypt hex(nonce_12 + ciphertext + tag_16) with AES-256-GCM + AAD */
function decryptContent(encryptedContentHex: string, key: Uint8Array, label: string): string {
  const contentBytes = hexToBytes(encryptedContentHex)
  const nonce = contentBytes.slice(0, 12)
  const ciphertext = contentBytes.slice(12)

  const cipher = gcm(key, nonce, utf8ToBytes(label))
  const plaintext = cipher.decrypt(ciphertext)
  return new TextDecoder().decode(plaintext)
}
